// ccp002-read-and-diff
// Hash-set diff of /miru-data/cc_completion_log.jsonl.
// State key: cc_completion_pinged_hashes (array of SHA-1 hex strings in workflow static data).
// New rows = rows whose SHA-1 hash is not in the pinged set.
//
// Restart-safe: n8n persists 'global' static data across container restarts when
// the execution finishes successfully (no exceptions downstream).
//
// State-wipe / first-run init: when pinged_hashes is empty/undefined AND file has rows,
// seed the set with all current row hashes and emit no pings. Anti-spam guarantee —
// historical rows never re-fire on workflow restart or static-data reset.
//
// Regression alert: fires ONCE (gated by cc_completion_regression_alerted) when
// pinged_hashes is non-empty AND fewer than 50% of those hashes are present in the
// current file. Clears automatically when >=50% are present again.
//
// ENOENT: missing file when pinged_hashes is non-empty triggers the regression alert.
//
// Note on best-effort hashing: new hashes are stored AFTER the diff is emitted.
// If a downstream Telegram send fails, the next poll will retry the row because
// its hash is not yet persisted. Trade-off: occasional duplicate sends are preferable
// to silently dropping rows.
const fs = require('fs');
const crypto = require('crypto');
const PATH = '/miru-data/cc_completion_log.jsonl';

function hashRow(line) {
  return crypto.createHash('sha1').update(line.trim()).digest('hex');
}

const staticData = ('global');
let pinnedHashes = staticData.cc_completion_pinged_hashes;
if (!Array.isArray(pinnedHashes)) pinnedHashes = [];
const pinnedSet = new Set(pinnedHashes);
const regressionAlerted = staticData.cc_completion_regression_alerted === true;

let content = '';
try {
  content = fs.readFileSync(PATH, 'utf8');
} catch (e) {
  if (e && e.code === 'ENOENT') {
    const shouldAlert = pinnedSet.size > 0 && !regressionAlerted;
    if (shouldAlert) staticData.cc_completion_regression_alerted = true;
    return [{ json: { new_rows: [], current_count: 0, regressed: shouldAlert, last_count: pinnedSet.size, _file_missing: true } }];
  }
  throw e;
}

const rows = content.split('
').filter(line => line.trim().length > 0);
const currentCount = rows.length;

// State-wipe init: pinged set empty but file has rows — seed silently, no pings.
if (pinnedSet.size === 0 && currentCount > 0) {
  staticData.cc_completion_pinged_hashes = rows.map(hashRow);
  staticData.cc_completion_regression_alerted = false;
  return [{ json: { new_rows: [], current_count: currentCount, regressed: false, last_count: 0, _init: true } }];
}

// Compute how many pinned hashes are still present in the current file.
const currentHashSet = new Set(rows.map(hashRow));
let presentCount = 0;
for (const h of pinnedSet) {
  if (currentHashSet.has(h)) presentCount++;
}
const presentRatio = pinnedSet.size > 0 ? presentCount / pinnedSet.size : 1;
const isRegressed = pinnedSet.size > 0 && presentRatio < 0.5;

if (isRegressed) {
  if (regressionAlerted) {
    // Already alerted; suppress until recovery.
    return [{ json: { new_rows: [], current_count: currentCount, regressed: false, last_count: pinnedSet.size } }];
  }
  staticData.cc_completion_regression_alerted = true;
  return [{ json: { new_rows: [], current_count: currentCount, regressed: true, last_count: pinnedSet.size } }];
}

// Recovery: clear alert flag when >=50% of pinned hashes are present again.
if (regressionAlerted) {
  staticData.cc_completion_regression_alerted = false;
}

// Diff: new rows are those not yet hashed.
const newRows = rows.filter(line => !pinnedSet.has(hashRow(line)));

// Store new hashes after diff (best-effort, see header comment).
staticData.cc_completion_pinged_hashes = [...pinnedHashes, ...newRows.map(hashRow)];

return [{ json: { new_rows: newRows, current_count: currentCount, regressed: false, last_count: pinnedSet.size } }];

// ccp004a-build-regression-msg
// File regressed below last-seen count. Build a single Telegram alert body.
const data = $input.item.json;
const text = '\u26A0 <b>cc_completion_log.jsonl regressed</b>\nrows now=' + (data.current_count != null ? data.current_count : '?') + ', last_seen=' + (data.last_count != null ? data.last_count : '?') + '\n<i>append-only convention violated; manual investigation required</i>';
const telegram_body = {
  chat_id: $env.TELEGRAM_CHAT_ID,
  text,
  parse_mode: 'HTML',
  disable_notification: false
};
return { json: { ...data, telegram_body } };

// ccp006-parse-and-build
// Parse one marker row, filter out non-PRO ticket_ids (BOOTSTRAP, etc.), build
// a Telegram message body shaped per PRO-99 spec. Sets _skip=true for rows that
// shouldn't ping (BOOTSTRAP, malformed JSON, unknown status).
//
// Filter: ticket_id must start with 'PRO-' (matches both real PRO-99 and synthetic
// PRO-TEST-99-1 test rows; excludes BOOTSTRAP and any future non-ticket markers).
function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const data = $input.item.json;
const rowStr = data.new_rows;

let row;
try { row = JSON.parse(rowStr); }
catch (e) {
  return { json: { _skip: true, _skip_reason: 'invalid JSON: ' + (e && e.message ? e.message : 'unknown'), raw: rowStr } };
}

const ticketId = row.ticket_id || '';
if (!/^PRO-/.test(ticketId)) {
  return { json: { _skip: true, _skip_reason: 'non-PRO ticket_id: ' + ticketId } };
}

const status = row.status || '';
let icon;
if (status === 'CONFIRMED_WORKING') { icon = '\u2705'; }
else if (status === 'INCONCLUSIVE') { icon = '\u26A0'; }
else if (status === 'FAILED') { icon = '\u274C \uD83D\uDEA8'; }
else { return { json: { _skip: true, _skip_reason: 'unknown status: ' + status } }; }

const summary = esc(row.summary || '');
const linearState = row.linear_state_after;
const prNumber = row.pr_number;
const mergeSha = row.merge_commit_sha;

const parts = [];
if (linearState != null) parts.push('<i>' + esc(linearState) + '</i>');
if (prNumber != null) parts.push('<a href="https://github.com/Dreighto/project-miru/pull/' + Number(prNumber) + '">PR #' + Number(prNumber) + '</a>');
if (mergeSha != null && typeof mergeSha === 'string') parts.push(esc(mergeSha.slice(0, 7)));
const thirdLine = parts.join(' \u00B7 ');

const text = icon + ' <b>' + esc(ticketId) + ' done</b>\n' + summary + (thirdLine ? '\n' + thirdLine : '');

const telegram_body = {
  chat_id: $env.TELEGRAM_CHAT_ID,
  text,
  parse_mode: 'HTML',
  disable_notification: false
};

return { json: { _skip: false, ticket_id: ticketId, status, telegram_body } };
